// Generated weights for NotificationTriage. Do not edit by hand.
//
// A logistic regression over the final assistant message (TF-IDF of words and
// word pairs), the turn's last tool names, and a few turn signals. Trained on
// 1,295 Integrated turns labelled ping or silent by an LLM against a rubric,
// and checked against 96 turns labelled by hand. The training data is not in
// the repository.
//
// The feature set is filtered so it carries nothing private: a word or word
// pair is a feature only if every word is a whole word in a public English
// WordPiece vocabulary, is not on a denylist of names, hosts and private
// project terms, and appears in turns from at least three projects. Tool
// features are Patterm's own MCP tools and the harnesses' built-in tools;
// other MCP servers' tools are not features.
// Feature order: words, then tools, then META.

export interface TriageWeights {
  words: string[];
  wordIdf: number[];
  wordCoef: number[];
  tools: string[];
  toolIdf: number[];
  toolCoef: number[];
  meta: Record<string, number>;
  intercept: number;
}

